import { useEffect, useState } from 'react'

function DocumentTitleUpdater({ unreadCount }) {
  useEffect(() => {
    document.title = unreadCount > 0 ? `(${unreadCount}) Inbox` : 'Inbox'
  }, [unreadCount])

  return null
}

